function doGet(e) {
  var isApi = e && e.parameter && e.parameter.api === "true";
  if (isApi) {
    try {
      var ss = SpreadsheetApp.getActiveSpreadsheet();
      var targetSheetName = e.parameter.sheet;
      
      if (targetSheetName === "tcas") {
        var sheetTcas = ss.getSheetByName("TCASDatabase");
        if (!sheetTcas) {
          return ContentService.createTextOutput(JSON.stringify([]))
            .setMimeType(ContentService.MimeType.JSON);
        }
        var dataTcas = readSheetData(sheetTcas);
        return ContentService.createTextOutput(JSON.stringify(dataTcas))
          .setMimeType(ContentService.MimeType.JSON);
      } else {
        var sheet1 = ss.getSheets()[0];
        var sheet2 = ss.getSheetByName("NoAwardsLog");
        var data1 = readSheetData(sheet1);
        var data2 = readSheetData(sheet2);
        var merged = data1.concat(data2);
        return ContentService.createTextOutput(JSON.stringify(merged))
          .setMimeType(ContentService.MimeType.JSON);
      }
      
      function readSheetData(sheet) {
        if (!sheet) return [];
        var data = sheet.getDataRange().getValues();
        if (data.length <= 1) return [];
        var headers = data[0];
        var arr = [];
        for (var i = 1; i < data.length; i++) {
          var obj = {};
          var hasData = false;
          for (var j = 0; j < headers.length; j++) {
            var val = data[i][j];
            obj[headers[j]] = val;
            if (val !== "") hasData = true;
          }
          if (hasData) arr.push(obj);
        }
        return arr;
      }
    } catch (err) {
      return ContentService.createTextOutput(JSON.stringify({ status: "error", message: err.toString() }))
        .setMimeType(ContentService.MimeType.JSON);
    }
  } else {
    return HtmlService.createHtmlOutput("✨ ระบบ API เชื่อมโยงฐานข้อมูลสารสนเทศสำเร็จ! แท็บคลังรางวัลและ TCAS พร้อมใช้งาน")
      .setTitle("SUW School Information API Status");
  }
}

function doPost(e) {
  try {
    var ss = SpreadsheetApp.getActiveSpreadsheet();
    var params = JSON.parse(e.postData.contents);
    var action = params.action || "create";
    var id = String(params.id || "");
    var sheetType = params.sheetType || "awards";
    
    function findRowById(sheet, idVal) {
      if (!idVal || !sheet) return null;
      var data = sheet.getDataRange().getValues();
      for (var i = 1; i < data.length; i++) {
        if (String(data[i][1]) === idVal) return i + 1;
      }
      return null;
    }

    if (sheetType === "tcas") {
      var sheetTcas = ss.getSheetByName("TCASDatabase");
      if (!sheetTcas) {
        sheetTcas = ss.insertSheet("TCASDatabase");
        sheetTcas.appendRow([
          "Timestamp", "id", "name", "room", "studentNumber", "university", "faculty", "major", "tcasRound", "status", "year", "notes", "addedBy"
        ]);
      }

      if (action === "delete") {
        var rowIndex = findRowById(sheetTcas, id);
        if (rowIndex) {
          sheetTcas.deleteRow(rowIndex);
          return ContentService.createTextOutput(JSON.stringify({ status: "success" })).setMimeType(ContentService.MimeType.JSON);
        }
        return ContentService.createTextOutput(JSON.stringify({ status: "error" })).setMimeType(ContentService.MimeType.JSON);
      }

      if (action === "edit") {
        var rowIndex = findRowById(sheetTcas, id);
        if (rowIndex) {
          sheetTcas.getRange(rowIndex, 3).setValue(params.name || "");
          sheetTcas.getRange(rowIndex, 4).setValue(params.room || "");
          sheetTcas.getRange(rowIndex, 5).setValue(Number(params.studentNumber || 0));
          sheetTcas.getRange(rowIndex, 6).setValue(params.university || "");
          sheetTcas.getRange(rowIndex, 7).setValue(params.faculty || "");
          sheetTcas.getRange(rowIndex, 8).setValue(params.major || "");
          sheetTcas.getRange(rowIndex, 9).setValue(params.tcasRound || "1");
          sheetTcas.getRange(rowIndex, 10).setValue(params.status || "confirmed");
          sheetTcas.getRange(rowIndex, 11).setValue(Number(params.year || 2569));
          sheetTcas.getRange(rowIndex, 12).setValue(params.notes || "");
          sheetTcas.getRange(rowIndex, 13).setValue(params.addedBy || "");
          return ContentService.createTextOutput(JSON.stringify({ status: "success" })).setMimeType(ContentService.MimeType.JSON);
        }
        return ContentService.createTextOutput(JSON.stringify({ status: "error" })).setMimeType(ContentService.MimeType.JSON);
      }

      sheetTcas.appendRow([
        new Date(),
        id || String(Date.now()),
        params.name || "",
        params.room || "",
        Number(params.studentNumber || 0),
        params.university || "",
        params.faculty || "",
        params.major || "",
        params.tcasRound || "1",
        params.status || "confirmed",
        Number(params.year || 2569),
        params.notes || "",
        params.addedBy || ""
      ]);
      return ContentService.createTextOutput(JSON.stringify({ status: "success" })).setMimeType(ContentService.MimeType.JSON);

    } else {
      var sheet1 = ss.getSheets()[0];
      var sheet2 = ss.getSheetByName("NoAwardsLog");
      if (!sheet2) {
        sheet2 = ss.insertSheet("NoAwardsLog");
        sheet2.appendRow(["Timestamp", "id", "title", "recipient", "role", "level", "category", "year", "date", "issuer", "description", "certificateImage", "addedBy"]);
      }

      function findAwardRow(idVal) {
        var sheets = [sheet1, sheet2];
        for (var s = 0; s < sheets.length; s++) {
          var sh = sheets[s];
          if (!sh) continue;
          var data = sh.getDataRange().getValues();
          for (var i = 1; i < data.length; i++) {
            if (String(data[i][1]) === idVal) return { sheet: sh, rowIndex: i + 1 };
          }
        }
        return null;
      }

      if (action === "delete") {
        var found = findAwardRow(id);
        if (found) {
          found.sheet.deleteRow(found.rowIndex);
          return ContentService.createTextOutput(JSON.stringify({ status: "success" })).setMimeType(ContentService.MimeType.JSON);
        }
        return ContentService.createTextOutput(JSON.stringify({ status: "error" })).setMimeType(ContentService.MimeType.JSON);
      }

      var imageUrl = params.certificateImage || "";
      if (imageUrl && imageUrl.indexOf("data:image") === 0) {
        var folderId = params.driveFolderId || "";
        if (folderId) {
          try {
            var folder = DriveApp.getFolderById(folderId);
            var splitData = imageUrl.split(",");
            var contentType = splitData[0].match(/:(.*?);/)[1];
            var base64Data = splitData[1];
            var decoded = Utilities.base64Decode(base64Data);
            var blob = Utilities.newBlob(decoded, contentType, "file_" + Date.now());
            var file = folder.createFile(blob);
            file.setSharing(DriveApp.Access.ANYONE_WITH_LINK, DriveApp.Permission.VIEW);
            imageUrl = file.getUrl();
          } catch (errUpload) {}
        }
      }

      if (action === "edit") {
        var found = findAwardRow(id);
        if (found) {
          var sh = found.sheet;
          var r = found.rowIndex;
          sh.getRange(r, 3).setValue(params.title || "");
          sh.getRange(r, 4).setValue(params.recipient || "");
          sh.getRange(r, 5).setValue(params.role || "student");
          sh.getRange(r, 6).setValue(params.level || "provincial");
          sh.getRange(r, 7).setValue(params.category || "science");
          sh.getRange(r, 8).setValue(Number(params.year || 2569));
          sh.getRange(r, 9).setValue(params.date || "");
          sh.getRange(r, 10).setValue(params.issuer || "");
          sh.getRange(r, 11).setValue(params.description || "");
          if (imageUrl) sh.getRange(r, 12).setValue(imageUrl);
          sh.getRange(r, 13).setValue(params.addedBy || "");
          return ContentService.createTextOutput(JSON.stringify({ status: "success", imageUrl: imageUrl })).setMimeType(ContentService.MimeType.JSON);
        }
        return ContentService.createTextOutput(JSON.stringify({ status: "error" })).setMimeType(ContentService.MimeType.JSON);
      }

      var targetSheet = (params.recipient === "[ไม่มี]") ? sheet2 : sheet1;
      targetSheet.appendRow([
        new Date(),
        id || String(Date.now()),
        params.title || "",
        params.recipient || "",
        params.role || "student",
        params.level || "provincial",
        params.category || "science",
        Number(params.year || 2569),
        params.date || "",
        params.issuer || "",
        params.description || "",
        imageUrl,
        params.addedBy || ""
      ]);
      return ContentService.createTextOutput(JSON.stringify({ status: "success", imageUrl: imageUrl })).setMimeType(ContentService.MimeType.JSON);
    }
  } catch (err) {
    return ContentService.createTextOutput(JSON.stringify({ status: "error", message: err.toString() })).setMimeType(ContentService.MimeType.JSON);
  }
}
